/// Returns true iff a and b are anagrams (same multiset of characters).
pub fn is_anagram(a: &str, b: &str) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    ac == bc
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_anagrams() {
        assert!(is_anagram("listen", "silent"));
        assert!(is_anagram("a", "a"));
        assert!(is_anagram("", ""));
        assert!(!is_anagram("hello", "world"));
        assert!(!is_anagram("abc", "ab"));
    }
}
